        setState(state => ({
          ...state,
          editorTabs: closeEventsFunctionsExtensionTabs(
            state.editorTabs,
            extensionName
          ),
        }));

        hasEventsBasedObject =
          hasEventsBasedObject || eventsBasedObjects.getCount() > 0;
